package com.example.starter.atm.domain;

/**
 * ATM（合成数据）。金额单位：分；时间单位：epoch 毫秒（UTC）。
 *
 * @param escortFrozen 押运异常冻结：true 表示该 ATM 已冻结，禁止编制后续计划
 */
public record Atm(
        Long id,
        String atmNo,
        String name,
        long cassetteCapacity,
        long avgDailyWithdrawal,
        boolean escortFrozen,
        long createdAt
) {
}

package com.example.starter.atm.domain;

/**
 * 押运员（合成数据）。
 *
 * @param frozen 责任人冻结：true 表示长短款逾期升级，禁止接新押运打卡任务
 */
public record Guard(
        Long id,
        String guardNo,
        String name,
        boolean frozen,
        long createdAt
) {
}

package com.example.starter.atm.domain;

/**
 * 款箱（合成数据）。容量与装填金额单位：分。
 */
public record CashBox(
        Long id,
        String boxNo,
        long atmId,
        long capacity,
        long loadedAmount,
        String status,
        long createdAt
) {
}

package com.example.starter.atm.domain;

/**
 * 押运打卡记录。两名不同押运员先后打卡；seq 按打卡时间定序（1=首人，2=次人）。
 */
public record EscortCheckin(
        Long id,
        long planId,
        long guardId,
        int seq,
        long checkinAt,
        long createdAt
) {
}

package com.example.starter.atm.domain;

/**
 * 计划事件流水。封存为终态后到达的清点/设备确认/打卡数据只登记 late=true 的迟到事件，不改变状态。
 */
public record PlanEvent(
        Long id,
        long planId,
        String eventType,
        boolean late,
        String detail,
        long eventAt,
        long createdAt
) {
}

