        if (guardRepository.count() == 0) {
            guardRepository.insert("GRD-A", "押运员甲", now);
            guardRepository.insert("GRD-B", "押运员乙", now);
            guardRepository.insert("GRD-C", "押运员丙", now);
        }
    }
}

